              "script": {
                "type": "literal",
                "value": "/******************************************************\n * Eligibility Engine (Phased, Field-ID based)\n * Auto-pass missing fields + omission reporting\n *\n * INPUTS:\n *   - submissionRecordId (string) REQUIRED\n *   - programsFound      (array)  OPTIONAL (Search records output)\n *\n * OUTPUTS:\n *   - phase1_locationPass (array)\n *   - phase2_incomePass   (array)\n *   - phase3_ownerPass    (array)\n *   - phase4_demoPass     (array) // final qualified\n *   - phase1_locationFail (array)\n *   - phase2_incomeFail   (array)\n *   - phase3_ownerFail    (array)\n *   - phase4_demoFail     (array)\n *   - omissionsByProgram  (object)\n *   - submissionDebug     (object)\n *   - eligibilityReport   (string)\n *\n * ✅ NEW OUTPUTS:\n *   - failsByProgram                (object) // merged fail reasons grouped by program & phase\n *   - failReasonsByProgramText      (string) // long-text friendly, grouped by program\n *   - failReasonsByProgramJsonText  (string) // pretty JSON string (also long-text friendly)\n ******************************************************/\n\nconst { submissionRecordId, programsFound } = input.config();\nif (!submissionRecordId) throw new Error(\"Missing input: submissionRecordId\");\n\n/* ---------------- CONFIG ---------------- */\n\nconst CONFIG = {\n  submissionTableId: \"tblVSxxZ4uyHZo8Mu\",\n  programsTableId: \"tblOR9OmQvyMybMGb\",\n\n  sub: {\n    locationJson: \"fldb1Nr1RLdrEPXvs\",\n    ownershipJson: \"fldjs7L8FJC7VhmXw\",\n    demoJson: \"fldBnxGyRjMbzW0Gu\",\n    incomeJson: \"fldq3zQd0BVOSf2EB\",\n    applicantName: \"fldHTkg7nTZYKhcVC\",\n    gisOwner: \"fldMfJ5oNOc0SPS6s\",\n  },\n\n  prog: {\n    name: \"fldHZ3j3ZUUy7ITEb\",\n    serviceArea: \"fldVPCPzs8oTrivD9\",\n    incomeRule: \"fld2Z07Cd7Db0F2qG\",\n    ownershipRule: \"fldUvbvM0ctQlmH4A\",\n    demoRule: \"fldlxRsFMf6ADznVo\",\n  },\n\n  demoRequiredMode: \"any\", // \"any\" or \"all\"\n  enforceOwnerMatchWhenOwnHomeRequired: false,\n};\n\n/* ---------------- Helpers ---------------- */\n\nfunction toIdArray(maybeArray) {\n  if (!maybeArray || !Array.isArray(maybeArray)) return [];\n  return maybeArray\n    .map((x) => (typeof x === \"string\" ? x : x?.id || x?.recordId || x?.airtableRecordId))\n    .filter(Boolean);\n}\n\nfunction firstVal(v) {\n  if (Array.isArray(v)) return v.find((x) => x !== null && x !== undefined && String(x).trim() !== \"\") ?? null;\n  return v === undefined ? null : v;\n}\n\nfunction normStr(x) {\n  return String(x ?? \"\")\n    .toLowerCase()\n    .trim()\n    .replace(/[^\\p{L}\\p{N}\\s]+/gu, \" \")\n    .replace(/\\s+/g, \" \");\n}\n\nfunction toNumber(x) {\n  const s = String(x ?? \"\").trim();\n  if (!s) return NaN;\n  const n = Number(s.replace(/[,$\\s]/g, \"\"));\n  return Number.isFinite(n) ? n : NaN;\n}\n\nfunction parseBoolMaybe(x) {\n  if (x === null || x === undefined) return null;\n  if (typeof x === \"boolean\") return x;\n  const s = String(x).trim().toLowerCase();\n  if (s === \"\") return null;\n  if ([\"true\", \"t\", \"yes\", \"y\", \"1\"].includes(s)) return true;\n  if ([\"false\", \"f\", \"no\", \"n\", \"0\"].includes(s)) return false;\n  return null;\n}\n\nfunction parseJsonMaybe(v) {\n  const raw = firstVal(v);\n  if (raw === null || raw === undefined || String(raw).trim() === \"\") return null;\n  if (typeof raw === \"object\") return raw;\n\n  const s = String(raw).trim();\n  try {\n    return JSON.parse(s);\n  } catch {}\n\n  if ((s.startsWith('\"') && s.endsWith('\"')) || (s.startsWith(\"'\") && s.endsWith(\"'\"))) {\n    const inner = s.slice(1, -1).replace(/\\\\\"/g, '\"');\n    return JSON.parse(inner);\n  }\n  return JSON.parse(s);\n}\n\nfunction arrayify(x) {\n  return Array.isArray(x) ? x : x ? [x] : [];\n}\n\n/* ---------------- Tables/Fields by ID ---------------- */\n\nconst subTable = base.getTable(CONFIG.submissionTableId);\nconst progTable = base.getTable(CONFIG.programsTableId);\n\nfunction F(table, fieldId) {\n  if (!fieldId) return null;\n  return table.getField(fieldId);\n}\n\nconst SUB_FIELDS = {\n  locationJson: F(subTable, CONFIG.sub.locationJson),\n  ownershipJson: F(subTable, CONFIG.sub.ownershipJson),\n  demoJson: F(subTable, CONFIG.sub.demoJson),\n  incomeJson: F(subTable, CONFIG.sub.incomeJson),\n  applicantName: CONFIG.sub.applicantName ? F(subTable, CONFIG.sub.applicantName) : null,\n  gisOwner: CONFIG.sub.gisOwner ? F(subTable, CONFIG.sub.gisOwner) : null,\n};\n\nconst PROG_FIELDS = {\n  name: F(progTable, CONFIG.prog.name),\n  serviceArea: F(progTable, CONFIG.prog.serviceArea),\n  incomeRule: F(progTable, CONFIG.prog.incomeRule),\n  ownershipRule: F(progTable, CONFIG.prog.ownershipRule),\n  demoRule: F(progTable, CONFIG.prog.demoRule),\n};\n\n/* ---------------- Normalize Submission ---------------- */\n\nfunction normalizeSubmission(subRec) {\n  const locObj = parseJsonMaybe(subRec.getCellValue(SUB_FIELDS.locationJson)) || {};\n  const ownObj = parseJsonMaybe(subRec.getCellValue(SUB_FIELDS.ownershipJson)) || {};\n  const demoObj = parseJsonMaybe(subRec.getCellValue(SUB_FIELDS.demoJson)) || {};\n  const incomeObj = parseJsonMaybe(subRec.getCellValue(SUB_FIELDS.incomeJson)) || [];\n\n  const loc = locObj.serviceArea ?? locObj.location ?? locObj ?? {};\n  const location = {\n    state: (loc.state ?? \"\").toString(),\n    county: (loc.county ?? \"\").toString(),\n    city: (loc.city ?? loc.town ?? \"\").toString(),\n    coa: parseBoolMaybe(loc.coa),\n    neighborhood: (loc.neighborhood ?? loc.legacy ?? \"\").toString(),\n  };\n\n  const oc = ownObj.ownershipCheck ?? ownObj ?? {};\n  const ownership = {\n    typeHome: (oc.typeHome ?? oc.homeType ?? \"\").toString(),\n    bldgValue: toNumber(oc.bldgValue ?? oc.blsgValue),\n    primaryRes: parseBoolMaybe(oc.primaryRes),\n    ownHome: parseBoolMaybe(oc.ownHome),\n    ownLot: parseBoolMaybe(oc.ownLot),\n    minTime: toNumber(oc.minTime),\n  };\n\n  const dc = demoObj.demoCheck ?? demoObj.demoGroup ?? demoObj ?? {};\n  const demoSet = new Set(\n    Object.entries(dc)\n      .filter(([, v]) => parseBoolMaybe(v) === true)\n      .map(([k]) => String(k).trim())\n  );\n\n  const incomeArr = arrayify(incomeObj)\n    .map((r) => r?.incomeCheck ?? r)\n    .filter(Boolean);\n  const incomeMap = {};\n  for (const r of incomeArr) {\n    const calc = String(r.calc ?? \"\").trim().toUpperCase();\n    const pct = toNumber(r.percent);\n    if (calc && Number.isFinite(pct)) incomeMap[calc] = pct;\n  }\n\n  const applicantName = SUB_FIELDS.applicantName ? subRec.getCellValueAsString(SUB_FIELDS.applicantName) || \"\" : \"\";\n  const gisOwner = SUB_FIELDS.gisOwner ? subRec.getCellValueAsString(SUB_FIELDS.gisOwner) || \"\" : \"\";\n\n  return { location, ownership, demoSet, incomeMap, applicantName, gisOwner };\n}\n\n/* ---------------- Normalize Program ---------------- */\n\nfunction normalizeProgram(rec) {\n  const name = rec.getCellValueAsString(PROG_FIELDS.name);\n\n  const saObj = parseJsonMaybe(rec.getCellValue(PROG_FIELDS.serviceArea)) || {};\n  const saArr = arrayify(saObj.serviceArea ?? saObj ?? []);\n  const serviceArea = new Map(); // scale -> Set(normStr(specific))\n  for (const item of saArr) {\n    const scale = normStr(item.scale ?? item.key ?? \"\");\n    const specific = String(item.specific ?? item.value ?? \"\").trim();\n    if (!scale || !specific) continue;\n    if (!serviceArea.has(scale)) serviceArea.set(scale, new Set());\n    serviceArea.get(scale).add(normStr(specific));\n  }\n\n  const incObj = parseJsonMaybe(rec.getCellValue(PROG_FIELDS.incomeRule)) || {};\n  const ic = incObj.incomeCheck ?? incObj ?? {};\n  const incomeRule = {\n    calc: String(ic.calc ?? \"\").trim().toUpperCase(),\n    max: toNumber(ic.max),\n  };\n\n  const ownObj = parseJsonMaybe(rec.getCellValue(PROG_FIELDS.ownershipRule)) || {};\n  const ownChecks = arrayify(ownObj.ownershipChecks ?? (ownObj.ownershipCheck ? [{ ownershipCheck: ownObj.ownershipCheck }] : []))\n    .map((x) => x?.ownershipCheck ?? x)\n    .filter(Boolean);\n\n  const demoObj = parseJsonMaybe(rec.getCellValue(PROG_FIELDS.demoRule)) || null;\n  let demoRule = null;\n  if (demoObj) {\n    const qual = String(demoObj.demoQual ?? \"\").trim(); // Required/Prioritized\n    const group = demoObj.demoGroup ?? demoObj.demoCheck ?? demoObj.demoCodes ?? {};\n    const codes = Object.entries(group)\n      .filter(([, v]) => parseBoolMaybe(v) === true)\n      .map(([k]) => String(k).trim());\n    if (qual && codes.length) demoRule = { qual, codes };\n  }\n\n  return { id: rec.id, name, serviceArea, incomeRule, ownershipChecks: ownChecks, demoRule };\n}\n\n/* ---------------- Omission tracking ---------------- */\n\nfunction addOmission(omissionsByProgram, prog, phase, msg) {\n  if (!omissionsByProgram[prog.id]) {\n    omissionsByProgram[prog.id] = { program: prog.name, programId: prog.id, items: [] };\n  }\n  omissionsByProgram[prog.id].items.push(`${phase}: ${msg}`);\n}\n\n/* ---------------- Phase checks (auto-pass missing) ---------------- */\n\nfunction checkScale(programMap, scaleKey, submissionValue) {\n  const allowed = programMap.get(normStr(scaleKey));\n  if (!allowed || allowed.size === 0) return { enforced: false, pass: true };\n\n  const sv = String(submissionValue ?? \"\").trim();\n  if (!sv) return { enforced: true, pass: true, missingSubmission: true, allowed: Array.from(allowed) };\n\n  const pass = allowed.has(normStr(sv));\n  return { enforced: true, pass, allowed: Array.from(allowed), actual: sv };\n}\n\nfunction phase1_location(sub, prog, omissionsByProgram) {\n  // State\n  {\n    const r = checkScale(prog.serviceArea, \"state\", sub.location.state);\n    if (!r.enforced) addOmission(omissionsByProgram, prog, \"phase1📍\", \"program omitted state restriction\");\n    else if (r.missingSubmission) addOmission(omissionsByProgram, prog, \"phase1📍\", \"submission missing state (auto-pass)\");\n    else if (!r.pass) return { pass: false, fails: [{ check: \"state\", actual: r.actual, allowed: r.allowed }] };\n  }\n\n  // County\n  {\n    const r = checkScale(prog.serviceArea, \"county\", sub.location.county);\n    if (!r.enforced) addOmission(omissionsByProgram, prog, \"phase1📍\", \"program omitted county restriction\");\n    else if (r.missingSubmission) addOmission(omissionsByProgram, prog, \"phase1📍\", \"submission missing county (auto-pass)\");\n    else if (!r.pass) return { pass: false, fails: [{ check: \"county\", actual: r.actual, allowed: r.allowed }] };\n  }\n\n  // City / town\n  {\n    const cityAllowed = prog.serviceArea.get(\"city\");\n    const townAllowed = prog.serviceArea.get(\"town\");\n    const enforced = (cityAllowed && cityAllowed.size) || (townAllowed && townAllowed.size);\n\n    if (!enforced) {\n      addOmission(omissionsByProgram, prog, \"phase1📍\", \"program omitted city/town restriction\");\n    } else {\n      const sv = String(sub.location.city ?? \"\").trim();\n      if (!sv) {\n        addOmission(omissionsByProgram, prog, \"phase1📍\", \"submission missing city/town (auto-pass)\");\n      } else {\n        const ok = (cityAllowed && cityAllowed.has(normStr(sv))) || (townAllowed && townAllowed.has(normStr(sv)));\n        if (!ok) {\n          return {\n            pass: false,\n            fails: [\n              {\n                check: \"city/town\",\n                actual: sv,\n                allowed: [...(cityAllowed ? Array.from(cityAllowed) : []), ...(townAllowed ? Array.from(townAllowed) : [])],\n              },\n            ],\n          };\n        }\n      }\n    }\n  }\n\n  // COA\n  {\n    const coaAllowed = prog.serviceArea.get(\"coa\");\n    if (!coaAllowed || !coaAllowed.size) {\n      addOmission(omissionsByProgram, prog, \"phase1📍\", \"program omitted coa restriction\");\n    } else {\n      const wantTrue = coaAllowed.has(\"true\") || coaAllowed.has(\"yes\");\n      if (sub.location.coa === null) {\n        addOmission(omissionsByProgram, prog, \"phase1📍\", \"submission missing coa (auto-pass)\");\n      } else if (wantTrue && sub.location.coa !== true) {\n        return { pass: false, fails: [{ check: \"coa\", actual: sub.location.coa, expected: true }] };\n      }\n    }\n  }\n\n  // Neighborhood / legacy\n  {\n    const r = checkScale(prog.serviceArea, \"neighborhood\", sub.location.neighborhood);\n    const r2 = checkScale(prog.serviceArea, \"legacy\", sub.location.neighborhood);\n    const enforced = r.enforced || r2.enforced;\n\n    if (!enforced) {\n      addOmission(omissionsByProgram, prog, \"phase1📍\", \"program omitted neighborhood/legacy restriction\");\n    } else {\n      const sv = String(sub.location.neighborhood ?? \"\").trim();\n      if (!sv) {\n        addOmission(omissionsByProgram, prog, \"phase1📍\", \"submission missing neighborhood/legacy (auto-pass)\");\n      } else {\n        const allowed = [\n          ...(prog.serviceArea.get(\"neighborhood\") ? Array.from(prog.serviceArea.get(\"neighborhood\")) : []),\n          ...(prog.serviceArea.get(\"legacy\") ? Array.from(prog.serviceArea.get(\"legacy\")) : []),\n        ];\n        const ok = allowed.includes(normStr(sv));\n        if (!ok) return { pass: false, fails: [{ check: \"neighborhood/legacy\", actual: sv, allowed }] };\n      }\n    }\n  }\n\n  return { pass: true };\n}\n\nfunction phase2_income(sub, prog, omissionsByProgram) {\n  const { calc, max } = prog.incomeRule;\n  if (!calc || !Number.isFinite(max)) {\n    addOmission(omissionsByProgram, prog, \"phase2💲\", \"program omitted income rule\");\n    return { pass: true };\n  }\n\n  const pct = sub.incomeMap[calc];\n  if (!Number.isFinite(pct)) {\n    addOmission(omissionsByProgram, prog, \"phase2💲\", `submission missing ${calc}% (auto-pass)`);\n    return { pass: true };\n  }\n\n  if (pct <= max) return { pass: true };\n  return { pass: false, fails: [{ check: `income:${calc}`, actual: pct, expected: `<= ${max}` }] };\n}\n\nfunction ownershipRulePasses(sub, prog, rule, omissionsByProgram) {\n  const fails = [];\n\n  // typeHome list\n  if (Array.isArray(rule.typeHome) && rule.typeHome.length) {\n    const sv = String(sub.ownership.typeHome ?? \"\").trim();\n    if (!sv) {\n      addOmission(omissionsByProgram, prog, \"phase3🏡\", \"submission missing typeHome (auto-pass)\");\n    } else {\n      const allowed = rule.typeHome.map(normStr);\n      if (!allowed.includes(normStr(sv))) fails.push({ check: \"typeHome\", actual: sv, allowed: rule.typeHome });\n    }\n  } else {\n    addOmission(omissionsByProgram, prog, \"phase3🏡\", \"program omitted typeHome restriction\");\n  }\n\n  // bldgValue max\n  if (rule.bldgValue !== undefined && rule.bldgValue !== null && String(rule.bldgValue) !== \"\") {\n    const maxVal = toNumber(rule.bldgValue);\n    const subVal = sub.ownership.bldgValue;\n    if (!Number.isFinite(subVal)) {\n      addOmission(omissionsByProgram, prog, \"phase3🏡\", \"submission missing bldgValue (auto-pass)\");\n    } else if (Number.isFinite(maxVal) && subVal > maxVal) {\n      fails.push({ check: \"bldgValue\", actual: subVal, expected: `<= ${maxVal}` });\n    }\n  } else {\n    addOmission(omissionsByProgram, prog, \"phase3🏡\", \"program omitted bldgValue restriction\");\n  }\n\n  // booleans\n  for (const k of [\"primaryRes\", \"ownHome\", \"ownLot\"]) {\n    if (rule[k] === true || rule[k] === false) {\n      if (sub.ownership[k] === null) {\n        addOmission(omissionsByProgram, prog, \"phase3🏡\", `submission missing ${k} (auto-pass)`);\n      } else if (sub.ownership[k] !== rule[k]) {\n        fails.push({ check: k, actual: sub.ownership[k], expected: rule[k] });\n      }\n    } else {\n      addOmission(omissionsByProgram, prog, \"phase3🏡\", `program omitted ${k} restriction`);\n    }\n  }\n\n  // minTime\n  if (rule.minTime !== undefined && rule.minTime !== null && String(rule.minTime) !== \"\") {\n    const minT = toNumber(rule.minTime);\n    const subT = sub.ownership.minTime;\n    if (!Number.isFinite(subT)) {\n      addOmission(omissionsByProgram, prog, \"phase3🏡\", \"submission missing minTime (auto-pass)\");\n    } else if (Number.isFinite(minT) && subT < minT) {\n      fails.push({ check: \"minTime\", actual: subT, expected: `>= ${minT}` });\n    }\n  } else {\n    addOmission(omissionsByProgram, prog, \"phase3🏡\", \"program omitted minTime restriction\");\n  }\n\n  // optional owner match\n  if (CONFIG.enforceOwnerMatchWhenOwnHomeRequired && rule.ownHome === true) {\n    const a = normStr(sub.applicantName);\n    const o = normStr(sub.gisOwner);\n    if (!a || !o) {\n      addOmission(omissionsByProgram, prog, \"phase3🏡\", \"submission missing applicantName or gisOwner (auto-pass owner match)\");\n    } else {\n      const aTok = new Set(a.split(\" \").filter((t) => t.length >= 3));\n      const oTok = new Set(o.split(\" \").filter((t) => t.length >= 3));\n      let hit = 0;\n      for (const t of aTok) if (oTok.has(t)) hit++;\n      if (hit < 1) fails.push({ check: \"gisOwner vs applicantName\", applicantName: sub.applicantName, gisOwner: sub.gisOwner });\n    }\n  }\n\n  return { pass: fails.length === 0, fails };\n}\n\nfunction phase3_ownership(sub, prog, omissionsByProgram) {\n  if (!prog.ownershipChecks.length) {\n    addOmission(omissionsByProgram, prog, \"phase3🏡\", \"program omitted ownership rules entirely\");\n    return { pass: true };\n  }\n\n  const attempts = prog.ownershipChecks.map((rule) => ownershipRulePasses(sub, prog, rule, omissionsByProgram));\n  if (attempts.some((a) => a.pass)) return { pass: true };\n  return { pass: false, fails: attempts.flatMap((a) => a.fails || []) };\n}\n\nfunction phase4_demo(sub, prog, omissionsByProgram) {\n  if (!prog.demoRule) {\n    addOmission(omissionsByProgram, prog, \"phase4👤\", \"program omitted demographic rule\");\n    return { pass: true };\n  }\n\n  const { qual, codes } = prog.demoRule;\n  const hits = codes.filter((c) => sub.demoSet.has(c));\n\n  if (qual.toLowerCase() === \"required\") {\n    if (!sub.demoSet || sub.demoSet.size === 0) {\n      addOmission(omissionsByProgram, prog, \"phase4👤\", \"submission missing demo flags (auto-pass required demo)\");\n      return { pass: true };\n    }\n\n    if (CONFIG.demoRequiredMode === \"all\") {\n      const pass = hits.length === codes.length;\n      return pass ? { pass: true } : { pass: false, fails: [{ check: \"demo(required:all)\", required: codes, hits }] };\n    } else {\n      const pass = hits.length > 0;\n      return pass ? { pass: true } : { pass: false, fails: [{ check: \"demo(required:any)\", required: codes, hits }] };\n    }\n  }\n\n  return { pass: true, prioritized: true, hits, required: codes };\n}\n\n/* ---------------- Fail reporting helpers ---------------- */\n\nfunction tallyFailChecks(failArray) {\n  const counts = {};\n  for (const row of failArray || []) {\n    for (const f of row.fails || []) {\n      const k = String(f.check || \"unknown\");\n      counts[k] = (counts[k] || 0) + 1;\n    }\n  }\n  return Object.entries(counts).sort((a, b) => b[1] - a[1]);\n}\n\nfunction formatTopFailChecks(failArray, limit = 10) {\n  const tallied = tallyFailChecks(failArray).slice(0, limit);\n  if (!tallied.length) return \"(none)\";\n  return tallied.map(([k, n]) => `- ${k}: ${n}`).join(\"\\n\");\n}\n\nfunction formatFailExamples(failArray, limitPrograms = 5) {\n  const slice = (failArray || []).slice(0, limitPrograms);\n  if (!slice.length) return \"(none)\";\n  return slice\n    .map((x) => {\n      const first = (x.fails || [])[0] || {};\n      const extra = first.expected !== undefined ? ` expected ${first.expected}` : first.allowed ? ` allowed ${JSON.stringify(first.allowed)}` : \"\";\n      const got = first.actual !== undefined ? ` got ${JSON.stringify(first.actual)}` : \"\";\n      return `- ${x.program}: ${first.check || \"unknown\"}${extra}${got}`;\n    })\n    .join(\"\\n\");\n}\n\n/* ---------------- ✅ NEW: Fail reasons (by program) ---------------- */\n\nfunction addFailsByProgram(failsByProgram, phaseLabel, failArray) {\n  for (const row of failArray || []) {\n    const pid = row.programId || row.programID || row.id;\n    if (!pid) continue;\n\n    if (!failsByProgram[pid]) {\n      failsByProgram[pid] = {\n        program: row.program || \"(unknown program)\",\n        programId: pid,\n        phases: {},\n      };\n    }\n\n    if (!failsByProgram[pid].phases[phaseLabel]) failsByProgram[pid].phases[phaseLabel] = [];\n    failsByProgram[pid].phases[phaseLabel].push(...(row.fails || []));\n  }\n}\n\nfunction formatOneFail(f) {\n  if (!f || typeof f !== \"object\") return String(f);\n\n  const parts = [];\n  parts.push(String(f.check || \"unknown\"));\n\n  if (\"expected\" in f) parts.push(`expected: ${JSON.stringify(f.expected)}`);\n  if (\"allowed\" in f) parts.push(`allowed: ${JSON.stringify(f.allowed)}`);\n  if (\"actual\" in f) parts.push(`actual: ${JSON.stringify(f.actual)}`);\n\n  if (\"required\" in f) parts.push(`required: ${JSON.stringify(f.required)}`);\n  if (\"hits\" in f) parts.push(`hits: ${JSON.stringify(f.hits)}`);\n\n  if (\"applicantName\" in f) parts.push(`applicantName: ${JSON.stringify(f.applicantName)}`);\n  if (\"gisOwner\" in f) parts.push(`gisOwner: ${JSON.stringify(f.gisOwner)}`);\n\n  return parts.join(\" | \");\n}\n\nfunction formatFailsByProgramText(failsByProgram) {\n  const progs = Object.values(failsByProgram || {}).sort((a, b) => String(a.program).localeCompare(String(b.program)));\n  if (!progs.length) return \"(none)\";\n\n  return progs\n    .map((p) => {\n      const phaseBlocks = Object.entries(p.phases || {})\n        .filter(([, arr]) => Array.isArray(arr) && arr.length)\n        .map(([phase, arr]) => {\n          const lines = arr.map((x) => `  - ${formatOneFail(x)}`).join(\"\\n\");\n          return `${phase}:\\n${lines}`;\n        })\n        .join(\"\\n\");\n\n      return `[${p.program}] (${p.programId})\\n${phaseBlocks || \"(no fails recorded)\"}`;\n    })\n    .join(\"\\n\\n\");\n}\n\nfunction clampText(s, maxChars = 90000) {\n  const str = String(s ?? \"\");\n  if (str.length <= maxChars) return str;\n  return str.slice(0, maxChars - 40) + \"\\n...(truncated due to length)\";\n}\n\n/* ---------------- ✅ NEW: EligibilityReport (explicit datapoints + auto-pass confirmations) ---------------- */\n\nconst PHASE_ORDER = [\"phase1📍\", \"phase2💲\", \"phase3🏡\", \"phase4👤\"];\n\nfunction statusEmoji(status) {\n  switch (status) {\n    case \"PASS\":\n      return \"✅\";\n    case \"FAIL\":\n      return \"❌\";\n    case \"AUTO-PASS\":\n      return \"⚠️\";\n    case \"NOT ENFORCED\":\n      return \"⏭️\";\n    case \"SKIPPED\":\n      return \"⛔\";\n    default:\n      return \"•\";\n  }\n}\n\nfunction fmt(v) {\n  if (v === undefined) return \"\";\n  if (v === null) return \"null\";\n  if (typeof v === \"string\") return JSON.stringify(v);\n  return JSON.stringify(v);\n}\n\nfunction uniqueLines(arr) {\n  const out = [];\n  const seen = new Set();\n  for (const s of arr || []) {\n    const k = String(s || \"\").trim();\n    if (!k || seen.has(k)) continue;\n    seen.add(k);\n    out.push(k);\n  }\n  return out;\n}\n\nfunction explainScale(programMap, scaleKey, submissionValue, labelOverride) {\n  const label = labelOverride || scaleKey;\n  const allowedSet = programMap.get(normStr(scaleKey));\n  const allowed = allowedSet ? Array.from(allowedSet) : [];\n\n  if (!allowedSet || allowedSet.size === 0) {\n    return { check: label, status: \"NOT ENFORCED\", note: `program omitted ${scaleKey} restriction` };\n  }\n\n  const sv = String(submissionValue ?? \"\").trim();\n  if (!sv) {\n    return { check: label, status: \"AUTO-PASS\", note: `submission missing ${scaleKey} (auto-pass)`, allowed };\n  }\n\n  const pass = allowedSet.has(normStr(sv));\n  return { check: label, status: pass ? \"PASS\" : \"FAIL\", actual: sv, allowed };\n}\n\nfunction explainPhase1Location(sub, prog) {\n  const checks = [];\n  checks.push(explainScale(prog.serviceArea, \"state\", sub.location.state, \"state\"));\n  checks.push(explainScale(prog.serviceArea, \"county\", sub.location.county, \"county\"));\n\n  // city/town combined\n  {\n    const cityAllowed = prog.serviceArea.get(\"city\");\n    const townAllowed = prog.serviceArea.get(\"town\");\n    const enforced = (cityAllowed && cityAllowed.size) || (townAllowed && townAllowed.size);\n\n    if (!enforced) {\n      checks.push({ check: \"city/town\", status: \"NOT ENFORCED\", note: \"program omitted city/town restriction\" });\n    } else {\n      const sv = String(sub.location.city ?? \"\").trim();\n      const allowed = [\n        ...(cityAllowed ? Array.from(cityAllowed) : []),\n        ...(townAllowed ? Array.from(townAllowed) : []),\n      ];\n      if (!sv) {\n        checks.push({ check: \"city/town\", status: \"AUTO-PASS\", note: \"submission missing city/town (auto-pass)\", allowed });\n      } else {\n        const ok = (cityAllowed && cityAllowed.has(normStr(sv))) || (townAllowed && townAllowed.has(normStr(sv)));\n        checks.push({ check: \"city/town\", status: ok ? \"PASS\" : \"FAIL\", actual: sv, allowed });\n      }\n    }\n  }\n\n  // coa\n  {\n    const coaAllowed = prog.serviceArea.get(\"coa\");\n    if (!coaAllowed || !coaAllowed.size) {\n      checks.push({ check: \"coa\", status: \"NOT ENFORCED\", note: \"program omitted coa restriction\" });\n    } else {\n      const wantTrue = coaAllowed.has(\"true\") || coaAllowed.has(\"yes\");\n      if (sub.location.coa === null) {\n        checks.push({\n          check: \"coa\",\n          status: \"AUTO-PASS\",\n          note: \"submission missing coa (auto-pass)\",\n          expected: wantTrue ? true : undefined,\n          allowed: Array.from(coaAllowed),\n        });\n      } else if (wantTrue) {\n        checks.push({ check: \"coa\", status: sub.location.coa === true ? \"PASS\" : \"FAIL\", actual: sub.location.coa, expected: true });\n      } else {\n        checks.push({\n          check: \"coa\",\n          status: \"PASS\",\n          actual: sub.location.coa,\n          note: \"coa restriction present but only 'true' enforcement is implemented\",\n        });\n      }\n    }\n  }\n\n  // neighborhood/legacy combined\n  {\n    const nb = prog.serviceArea.get(\"neighborhood\");\n    const lg = prog.serviceArea.get(\"legacy\");\n    const enforced = (nb && nb.size) || (lg && lg.size);\n\n    if (!enforced) {\n      checks.push({ check: \"neighborhood/legacy\", status: \"NOT ENFORCED\", note: \"program omitted neighborhood/legacy restriction\" });\n    } else {\n      const sv = String(sub.location.neighborhood ?? \"\").trim();\n      const allowed = [...(nb ? Array.from(nb) : []), ...(lg ? Array.from(lg) : [])];\n      if (!sv) {\n        checks.push({\n          check: \"neighborhood/legacy\",\n          status: \"AUTO-PASS\",\n          note: \"submission missing neighborhood/legacy (auto-pass)\",\n          allowed,\n        });\n      } else {\n        const ok = allowed.includes(normStr(sv));\n        checks.push({ check: \"neighborhood/legacy\", status: ok ? \"PASS\" : \"FAIL\", actual: sv, allowed });\n      }\n    }\n  }\n\n  const pass = !checks.some((c) => c.status === \"FAIL\");\n  return { phase: \"phase1📍\", pass, checks };\n}\n\nfunction explainPhase2Income(sub, prog) {\n  const checks = [];\n  const { calc, max } = prog.incomeRule;\n\n  if (!calc || !Number.isFinite(max)) {\n    checks.push({ check: \"income rule\", status: \"NOT ENFORCED\", note: \"program omitted income rule\" });\n    return { phase: \"phase2💲\", pass: true, checks };\n  }\n\n  const pct = sub.incomeMap[calc];\n  if (!Number.isFinite(pct)) {\n    checks.push({\n      check: `income:${calc}`,\n      status: \"AUTO-PASS\",\n      note: `submission missing ${calc}% (auto-pass)`,\n      expected: `<= ${max}`,\n    });\n    return { phase: \"phase2💲\", pass: true, checks };\n  }\n\n  checks.push({ check: `income:${calc}`, status: pct <= max ? \"PASS\" : \"FAIL\", actual: pct, expected: `<= ${max}` });\n  return { phase: \"phase2💲\", pass: !checks.some((c) => c.status === \"FAIL\"), checks };\n}\n\nfunction explainOwnershipRule(sub, rule, idx) {\n  const checks = [];\n  const labelPrefix = `rule#${idx + 1}`;\n\n  // typeHome\n  if (Array.isArray(rule.typeHome) && rule.typeHome.length) {\n    const sv = String(sub.ownership.typeHome ?? \"\").trim();\n    if (!sv) {\n      checks.push({ check: `${labelPrefix}.typeHome`, status: \"AUTO-PASS\", note: \"submission missing typeHome (auto-pass)\", allowed: rule.typeHome });\n    } else {\n      const allowedNorm = rule.typeHome.map(normStr);\n      checks.push({ check: `${labelPrefix}.typeHome`, status: allowedNorm.includes(normStr(sv)) ? \"PASS\" : \"FAIL\", actual: sv, allowed: rule.typeHome });\n    }\n  } else {\n    checks.push({ check: `${labelPrefix}.typeHome`, status: \"NOT ENFORCED\", note: \"program omitted typeHome restriction\" });\n  }\n\n  // bldgValue\n  if (rule.bldgValue !== undefined && rule.bldgValue !== null && String(rule.bldgValue) !== \"\") {\n    const maxVal = toNumber(rule.bldgValue);\n    const subVal = sub.ownership.bldgValue;\n    if (!Number.isFinite(subVal)) {\n      checks.push({\n        check: `${labelPrefix}.bldgValue`,\n        status: \"AUTO-PASS\",\n        note: \"submission missing bldgValue (auto-pass)\",\n        expected: Number.isFinite(maxVal) ? `<= ${maxVal}` : undefined,\n      });\n    } else {\n      checks.push({\n        check: `${labelPrefix}.bldgValue`,\n        status: Number.isFinite(maxVal) && subVal > maxVal ? \"FAIL\" : \"PASS\",\n        actual: subVal,\n        expected: Number.isFinite(maxVal) ? `<= ${maxVal}` : undefined,\n      });\n    }\n  } else {\n    checks.push({ check: `${labelPrefix}.bldgValue`, status: \"NOT ENFORCED\", note: \"program omitted bldgValue restriction\" });\n  }\n\n  // booleans\n  for (const k of [\"primaryRes\", \"ownHome\", \"ownLot\"]) {\n    if (rule[k] === true || rule[k] === false) {\n      const subVal = sub.ownership[k];\n      if (subVal === null) {\n        checks.push({ check: `${labelPrefix}.${k}`, status: \"AUTO-PASS\", note: `submission missing ${k} (auto-pass)`, expected: rule[k] });\n      } else {\n        checks.push({ check: `${labelPrefix}.${k}`, status: subVal === rule[k] ? \"PASS\" : \"FAIL\", actual: subVal, expected: rule[k] });\n      }\n    } else {\n      checks.push({ check: `${labelPrefix}.${k}`, status: \"NOT ENFORCED\", note: `program omitted ${k} restriction` });\n    }\n  }\n\n  // minTime\n  if (rule.minTime !== undefined && rule.minTime !== null && String(rule.minTime) !== \"\") {\n    const minT = toNumber(rule.minTime);\n    const subT = sub.ownership.minTime;\n    if (!Number.isFinite(subT)) {\n      checks.push({\n        check: `${labelPrefix}.minTime`,\n        status: \"AUTO-PASS\",\n        note: \"submission missing minTime (auto-pass)\",\n        expected: Number.isFinite(minT) ? `>= ${minT}` : undefined,\n      });\n    } else {\n      checks.push({\n        check: `${labelPrefix}.minTime`,\n        status: Number.isFinite(minT) && subT < minT ? \"FAIL\" : \"PASS\",\n        actual: subT,\n        expected: Number.isFinite(minT) ? `>= ${minT}` : undefined,\n      });\n    }\n  } else {\n    checks.push({ check: `${labelPrefix}.minTime`, status: \"NOT ENFORCED\", note: \"program omitted minTime restriction\" });\n  }\n\n  // optional owner match\n  if (CONFIG.enforceOwnerMatchWhenOwnHomeRequired && rule.ownHome === true) {\n    const a = normStr(sub.applicantName);\n    const o = normStr(sub.gisOwner);\n\n    if (!a || !o) {\n      checks.push({\n        check: `${labelPrefix}.ownerMatch`,\n        status: \"AUTO-PASS\",\n        note: \"submission missing applicantName or gisOwner (auto-pass owner match)\",\n        expected: \"applicantName token overlap with gisOwner\",\n      });\n    } else {\n      const aTok = new Set(a.split(\" \").filter((t) => t.length >= 3));\n      const oTok = new Set(o.split(\" \").filter((t) => t.length >= 3));\n      let hit = 0;\n      for (const t of aTok) if (oTok.has(t)) hit++;\n      checks.push({\n        check: `${labelPrefix}.ownerMatch`,\n        status: hit >= 1 ? \"PASS\" : \"FAIL\",\n        actual: { applicantName: sub.applicantName, gisOwner: sub.gisOwner, tokenHits: hit },\n        expected: \">= 1 shared token (len>=3)\",\n      });\n    }\n  }\n\n  return { ruleIndex: idx + 1, pass: !checks.some((c) => c.status === \"FAIL\"), checks };\n}\n\nfunction explainPhase3Ownership(sub, prog) {\n  if (!prog.ownershipChecks.length) {\n    return {\n      phase: \"phase3🏡\",\n      pass: true,\n      checks: [{ check: \"ownership rules\", status: \"NOT ENFORCED\", note: \"program omitted ownership rules entirely\" }],\n      rules: [],\n      winnerRuleIndex: null,\n    };\n  }\n\n  const rules = prog.ownershipChecks.map((rule, idx) => explainOwnershipRule(sub, rule, idx));\n  const winner = rules.find((r) => r.pass) || null;\n\n  return {\n    phase: \"phase3🏡\",\n    pass: !!winner,\n    checks: [],\n    rules,\n    winnerRuleIndex: winner ? winner.ruleIndex : null,\n  };\n}\n\nfunction explainPhase4Demo(sub, prog) {\n  const checks = [];\n\n  if (!prog.demoRule) {\n    checks.push({ check: \"demo rule\", status: \"NOT ENFORCED\", note: \"program omitted demographic rule\" });\n    return { phase: \"phase4👤\", pass: true, prioritized: false, checks };\n  }\n\n  const { qual, codes } = prog.demoRule;\n  const hits = codes.filter((c) => sub.demoSet.has(c));\n\n  if (String(qual).toLowerCase() === \"required\") {\n    if (!sub.demoSet || sub.demoSet.size === 0) {\n      checks.push({\n        check: \"demo(required)\",\n        status: \"AUTO-PASS\",\n        note: \"submission missing demo flags (auto-pass required demo)\",\n        expected: CONFIG.demoRequiredMode === \"all\" ? `must include ALL of ${fmt(codes)}` : `must include ANY of ${fmt(codes)}`,\n      });\n      return { phase: \"phase4👤\", pass: true, prioritized: false, checks };\n    }\n\n    if (CONFIG.demoRequiredMode === \"all\") {\n      const pass = hits.length === codes.length;\n      checks.push({ check: \"demo(required:all)\", status: pass ? \"PASS\" : \"FAIL\", actual: hits, expected: codes });\n      return { phase: \"phase4👤\", pass, prioritized: false, checks };\n    } else {\n      const pass = hits.length > 0;\n      checks.push({ check: \"demo(required:any)\", status: pass ? \"PASS\" : \"FAIL\", actual: hits, expected: codes });\n      return { phase: \"phase4👤\", pass, prioritized: false, checks };\n    }\n  }\n\n  checks.push({ check: \"demo(prioritized)\", status: \"PASS\", actual: hits, expected: codes, note: \"prioritized demo (does not disqualify)\" });\n  return { phase: \"phase4👤\", pass: true, prioritized: true, checks };\n}\n\nfunction explainProgramDecision(sub, prog) {\n  const phases = {};\n\n  const p1 = explainPhase1Location(sub, prog);\n  phases[p1.phase] = p1;\n  if (!p1.pass) return { program: prog.name, programId: prog.id, result: \"FAIL\", failPhase: p1.phase, phases };\n\n  const p2 = explainPhase2Income(sub, prog);\n  phases[p2.phase] = p2;\n  if (!p2.pass) return { program: prog.name, programId: prog.id, result: \"FAIL\", failPhase: p2.phase, phases };\n\n  const p3 = explainPhase3Ownership(sub, prog);\n  phases[p3.phase] = p3;\n  if (!p3.pass) return { program: prog.name, programId: prog.id, result: \"FAIL\", failPhase: p3.phase, phases };\n\n  const p4 = explainPhase4Demo(sub, prog);\n  phases[p4.phase] = p4;\n  if (!p4.pass) return { program: prog.name, programId: prog.id, result: \"FAIL\", failPhase: p4.phase, phases };\n\n  return { program: prog.name, programId: prog.id, result: \"PASS\", failPhase: null, phases, prioritized: !!p4.prioritized };\n}\n\nfunction collectNeedsConfirmation(decision) {\n  const needs = [];\n\n  for (const phase of PHASE_ORDER) {\n    const pr = decision.phases?.[phase];\n    if (!pr) continue;\n    if (!pr.pass) break; // only confirmations that contributed to passing path\n\n    if (phase !== \"phase3🏡\") {\n      for (const c of pr.checks || []) {\n        if (c.status === \"AUTO-PASS\") {\n          const req = c.expected ? ` expected ${fmt(c.expected)}` : c.allowed ? ` allowed ${fmt(c.allowed)}` : \"\";\n          needs.push(`${phase} → ${c.check}${req}`);\n        }\n      }\n    } else {\n      const winner = (pr.rules || []).find((r) => r.ruleIndex === pr.winnerRuleIndex);\n      if (winner) {\n        for (const c of winner.checks || []) {\n          if (c.status === \"AUTO-PASS\") {\n            const req = c.expected ? ` expected ${fmt(c.expected)}` : c.allowed ? ` allowed ${fmt(c.allowed)}` : \"\";\n            needs.push(`${phase} → ${c.check}${req}`);\n          }\n        }\n      }\n    }\n  }\n\n  return uniqueLines(needs);\n}\n\nfunction collectProgramRuleMissing(decision) {\n  const missing = [];\n\n  for (const phase of PHASE_ORDER) {\n    const pr = decision.phases?.[phase];\n    if (!pr) continue;\n\n    if (phase !== \"phase3🏡\") {\n      for (const c of pr.checks || []) {\n        if (c.status === \"NOT ENFORCED\") missing.push(`${phase} → ${c.check}: ${c.note || \"not enforced\"}`);\n      }\n    } else {\n      for (const r of pr.rules || []) {\n        for (const c of r.checks || []) {\n          if (c.status === \"NOT ENFORCED\") missing.push(`${phase} → ${c.check}: ${c.note || \"not enforced\"}`);\n        }\n      }\n      for (const c of pr.checks || []) {\n        if (c.status === \"NOT ENFORCED\") missing.push(`${phase} → ${c.check}: ${c.note || \"not enforced\"}`);\n      }\n    }\n  }\n\n  return uniqueLines(missing);\n}\n\nfunction formatCheckLine(c) {\n  const bits = [];\n  if (c.actual !== undefined) bits.push(`actual: ${fmt(c.actual)}`);\n  if (c.expected !== undefined) bits.push(`expected: ${fmt(c.expected)}`);\n  if (c.allowed !== undefined) bits.push(`allowed: ${fmt(c.allowed)}`);\n  if (c.note) bits.push(`note: ${c.note}`);\n  const detail = bits.length ? ` | ${bits.join(\" | \")}` : \"\";\n  return `  - ${statusEmoji(c.status)} ${c.check}: ${c.status}${detail}`;\n}\n\nfunction formatPhaseBlock(phaseResult) {\n  if (!phaseResult) return \"\";\n  const header = `${phaseResult.phase}: ${phaseResult.pass ? \"✅ PASS\" : \"❌ FAIL\"}`;\n\n  if (phaseResult.phase !== \"phase3🏡\") {\n    const lines = (phaseResult.checks || []).map(formatCheckLine).join(\"\\n\");\n    return `${header}\\n${lines || \"  (no checks)\"}`;\n  }\n\n  if (phaseResult.rules && phaseResult.rules.length) {\n    const ruleLines = phaseResult.rules\n      .map((r) => {\n        const rHead = `  Rule #${r.ruleIndex}: ${r.pass ? \"✅ PASS\" : \"❌ FAIL\"}` + (phaseResult.winnerRuleIndex === r.ruleIndex ? \" (chosen)\" : \"\");\n        const cLines = (r.checks || []).map(formatCheckLine).join(\"\\n\");\n        return `${rHead}\\n${cLines || \"    (no checks)\"}`;\n      })\n      .join(\"\\n\");\n    return `${header} (winner rule: ${phaseResult.winnerRuleIndex || \"none\"})\\n${ruleLines}`;\n  }\n\n  const lines = (phaseResult.checks || []).map(formatCheckLine).join(\"\\n\");\n  return `${header}\\n${lines || \"  (no checks)\"}`;\n}\n\nfunction buildEligibilityReportDetailed(sub, decisionsByProgram) {\n  const decisions = Object.values(decisionsByProgram || {}).sort((a, b) => String(a.program).localeCompare(String(b.program)));\n\n  const qualified = decisions.filter((d) => d.result === \"PASS\");\n  const failed = decisions.filter((d) => d.result !== \"PASS\");\n\n  const submissionSnapshot =\n    `Submission datapoints used:\\n` +\n    `- Location: state=${fmt(sub.location.state)} | county=${fmt(sub.location.county)} | city=${fmt(sub.location.city)} | coa=${fmt(sub.location.coa)} | neighborhood=${fmt(sub.location.neighborhood)}\\n` +\n    `- Ownership: typeHome=${fmt(sub.ownership.typeHome)} | bldgValue=${fmt(sub.ownership.bldgValue)} | primaryRes=${fmt(sub.ownership.primaryRes)} | ownHome=${fmt(sub.ownership.ownHome)} | ownLot=${fmt(sub.ownership.ownLot)} | minTime=${fmt(sub.ownership.minTime)}\\n` +\n    `- IncomeMap: ${fmt(sub.incomeMap)}\\n` +\n    `- Demo flags: ${fmt(Array.from(sub.demoSet))}\\n` +\n    (sub.applicantName || sub.gisOwner ? `- Names: applicantName=${fmt(sub.applicantName)} | gisOwner=${fmt(sub.gisOwner)}\\n` : \"\");\n\n  function formatProgramDecision(d) {\n    const needsConfirm = collectNeedsConfirmation(d);\n    const programMissing = collectProgramRuleMissing(d);\n\n    const phaseBlocks = PHASE_ORDER.map((ph) => (d.phases?.[ph] ? formatPhaseBlock(d.phases[ph]) : \"\")).filter(Boolean).join(\"\\n\");\n\n    const resultLine =\n      d.result === \"PASS\"\n        ? `Result: ✅ QUALIFIED${d.prioritized ? \" (demo prioritized match present)\" : \"\"}`\n        : `Result: ❌ NOT QUALIFIED (failed at ${d.failPhase})`;\n\n    const confirmBlock = needsConfirm.length\n      ? `Needs confirmation (AUTO-PASS used due to missing submission datapoints):\\n- ${needsConfirm.join(\"\\n- \")}`\n      : `Needs confirmation (AUTO-PASS): (none)`;\n\n    const missingBlock = programMissing.length\n      ? `Program rule missing / not enforced (program-side omissions):\\n- ${programMissing.join(\"\\n- \")}`\n      : `Program rule missing / not enforced: (none)`;\n\n    return `[${d.program}] (${d.programId})\\n${resultLine}\\n\\nPhase breakdown:\\n${phaseBlocks}\\n\\n${confirmBlock}\\n\\n${missingBlock}\\n`;\n  }\n\n  const header =\n    `ELIGIBILITY REPORT\\n` +\n    `=================\\n\\n` +\n    submissionSnapshot +\n    `\\n---\\n` +\n    `Qualified programs: ${qualified.length}\\n` +\n    `Not qualified programs: ${failed.length}\\n`;\n\n  const qualifiedBlock = qualified.length\n    ? `\\n\\n✅ QUALIFIED (details)\\n----------------------\\n\\n${qualified.map(formatProgramDecision).join(\"\\n\\n\")}`\n    : `\\n\\n✅ QUALIFIED (details)\\n----------------------\\n\\n(none)`;\n\n  const failedBlock = failed.length\n    ? `\\n\\n❌ NOT QUALIFIED (details)\\n--------------------------\\n\\n${failed.map(formatProgramDecision).join(\"\\n\\n\")}`\n    : `\\n\\n❌ NOT QUALIFIED (details)\\n--------------------------\\n\\n(none)`;\n\n  return header + qualifiedBlock + failedBlock;\n}\n\n/* ---------------- MAIN ---------------- */\n\nconst omissionsByProgram = {};\n\n// fail arrays\nconst phase1_locationFail = [];\nconst phase2_incomeFail = [];\nconst phase3_ownerFail = [];\nconst phase4_demoFail = [];\n\n// Load submission\nconst subRec = await subTable.selectRecordAsync(submissionRecordId, {\n  fields: Object.values(SUB_FIELDS).filter(Boolean),\n});\nif (!subRec) throw new Error(`Submission record not found: ${submissionRecordId}`);\n\nconst sub = normalizeSubmission(subRec);\noutput.set(\"locationDebug\", sub.location);\n\n// Load programs once\nconst programIds = new Set(toIdArray(programsFound));\nconst progQuery = await progTable.selectRecordsAsync({\n  fields: Object.values(PROG_FIELDS),\n});\nconst allPrograms = progQuery.records\n  .filter((r) => programIds.size === 0 || programIds.has(r.id))\n  .map(normalizeProgram);\n\n// Phase 1 📍\nconst phase1_locationPass = [];\nconst phase1Programs = [];\nfor (const p of allPrograms) {\n  const r = phase1_location(sub, p, omissionsByProgram);\n  if (r.pass) {\n    phase1_locationPass.push({ program: p.name, programId: p.id });\n    phase1Programs.push(p);\n  } else {\n    phase1_locationFail.push({ program: p.name, programId: p.id, fails: r.fails || [] });\n  }\n}\n\n// Phase 2 💲\nconst phase2_incomePass = [];\nconst phase2Programs = [];\nfor (const p of phase1Programs) {\n  const r = phase2_income(sub, p, omissionsByProgram);\n  if (r.pass) {\n    phase2_incomePass.push({ program: p.name, programId: p.id });\n    phase2Programs.push(p);\n  } else {\n    phase2_incomeFail.push({ program: p.name, programId: p.id, fails: r.fails || [] });\n  }\n}\n\n// Phase 3 🏡\nconst phase3_ownerPass = [];\nconst phase3Programs = [];\nfor (const p of phase2Programs) {\n  const r = phase3_ownership(sub, p, omissionsByProgram);\n  if (r.pass) {\n    phase3_ownerPass.push({ program: p.name, programId: p.id });\n    phase3Programs.push(p);\n  } else {\n    phase3_ownerFail.push({ program: p.name, programId: p.id, fails: r.fails || [] });\n  }\n}\n\n// Phase 4 👤\nconst phase4_demoPass = [];\nfor (const p of phase3Programs) {\n  const r = phase4_demo(sub, p, omissionsByProgram);\n  if (r.pass) {\n    phase4_demoPass.push({ program: p.name, programId: p.id, prioritized: !!r.prioritized });\n  } else {\n    phase4_demoFail.push({ program: p.name, programId: p.id, fails: r.fails || [] });\n  }\n}\n\n// ✅ NEW: Fail reasons by program (merged across phases)\nconst failsByProgram = {};\naddFailsByProgram(failsByProgram, \"phase1📍\", phase1_locationFail);\naddFailsByProgram(failsByProgram, \"phase2💲\", phase2_incomeFail);\naddFailsByProgram(failsByProgram, \"phase3🏡\", phase3_ownerFail);\naddFailsByProgram(failsByProgram, \"phase4👤\", phase4_demoFail);\n\nconst failReasonsByProgramText = clampText(formatFailsByProgramText(failsByProgram));\nconst failReasonsByProgramJsonText = clampText(JSON.stringify(failsByProgram, null, 2));\n\n// ✅ NEW: Detailed eligibility report (explicit datapoints + auto-pass confirmations)\nconst decisionsByProgram = {};\nfor (const p of allPrograms) {\n  decisionsByProgram[p.id] = explainProgramDecision(sub, p);\n}\nconst eligibilityReport = clampText(buildEligibilityReportDetailed(sub, decisionsByProgram));\n\n// Outputs\noutput.set(\"phase1_locationPass\", phase1_locationPass);\noutput.set(\"phase2_incomePass\", phase2_incomePass);\noutput.set(\"phase3_ownerPass\", phase3_ownerPass);\noutput.set(\"phase4_demoPass\", phase4_demoPass);\n\noutput.set(\"phase1_locationFail\", phase1_locationFail);\noutput.set(\"phase2_incomeFail\", phase2_incomeFail);\noutput.set(\"phase3_ownerFail\", phase3_ownerFail);\noutput.set(\"phase4_demoFail\", phase4_demoFail);\n\noutput.set(\"omissionsByProgram\", omissionsByProgram);\n\n// ✅ NEW OUTPUTS\noutput.set(\"failsByProgram\", failsByProgram);\noutput.set(\"failReasonsByProgramText\", failReasonsByProgramText);\noutput.set(\"failReasonsByProgramJsonText\", failReasonsByProgramJsonText);\n\n// Optional but very helpful for debugging\noutput.set(\"submissionDebug\", {\n  location: sub.location,\n  ownership: sub.ownership,\n  incomeMap: sub.incomeMap,\n  demoCodes: Array.from(sub.demoSet),\n  applicantName: sub.applicantName,\n  gisOwner: sub.gisOwner,\n});\n\noutput.set(\"eligibilityReport\", eligibilityReport);\n\nconsole.log(sub);"
