const sizeKey = Object.keys(data)[0];
const sizeBlock = data[sizeKey];

function pickEffective(calcName) {
  const block = sizeBlock?.[calcName];
  if (!block) return null;

  const best = Object.values(block)
    .map(v => ({
      annual: toNumber(v.annualDollars),
      eDate: normalizeUnix(v.eDate),
    }))
    .filter(x => Number.isFinite(x.annual) && Number.isFinite(x.eDate) && x.eDate <= appMs)
    .sort((a, b) => b.eDate - a.eDate)[0];

  if (!best) return null;

  const pct = Math.round((gross / best.annual) * 100);
  return { incomeCheck: { calc: calcName, percent: String(pct) } };
}

const out = [];
const ami = pickEffective("AMI"); if (ami) out.push(ami);
const fpl = pickEffective("FPL"); if (fpl) out.push(fpl);

output.set("incomeChecks", out);
output.set("incomeChecksJson", JSON.stringify(out));

